use std::{
    collections::HashSet,
    fs,
    path::{Path, PathBuf},
};

use anyhow::Result;
use rayon::iter::{IntoParallelRefIterator, ParallelIterator};

use crate::sqlite::DatabaseRow;
mod cli;
mod compress;
mod config;
mod sqlite;

static VERBOSE: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
static LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

#[macro_export]
macro_rules! input {

    ($($arg:tt)*) => {{
        use ::std::io::Write as _;
        let _guard = $crate::LOCK.lock().unwrap_or_else(|e| e.into_inner());
        print!($($arg)*);
        ::std::io::stdout().flush().expect("stdout flush failed");
        let mut buf = String::new();
        ::std::io::stdin().read_line(&mut buf).expect("input read failed");

        if buf.ends_with('\n') {
            buf.pop();
            if buf.ends_with('\r') {
                buf.pop();
            }
        }
        buf
    }};
}

#[macro_export]
macro_rules! verbose_println {
    ($($arg:tt)*) => {
        if *$crate::VERBOSE.get().unwrap_or(&false){
            let info = format!("[{}:{}]",file!(),line!());
            let msg = format!($($arg)*);
            eprintln!("{info}{msg}");
        }
    };
}
#[macro_export]
macro_rules! verbose_dbg {
    ($arg:expr) => {{
        if *$crate::VERBOSE.get().unwrap_or(&false) {
            dbg!($arg)
        } else {
            $arg
        }
    }};
}

fn main() -> Result<()> {
    let todo = verbose_dbg!(config::init())?;
    let db_path = verbose_dbg!(todo.trash_dir.join("database.db"));
    let mut db = sqlite::Database::new(&db_path)?;
    if todo.list {
        db.list_all()?;
    }
    if todo.clear {
        match input!("It'll delete all your data forever. Do you really want to continue?[Y/n] ")
            .as_str()
        {
            "Y" | "y" => {
                db.clear()?;
            }
            _ => {}
        }
    }
    if todo.autoclearn {
        let set: HashSet<PathBuf> = db
            .select_all()?
            .par_iter()
            .filter_map(|x| {
                let p = PathBuf::from(&x.present_path);
                if p.exists() {
                    Some(p.canonicalize().unwrap())
                } else {
                    None
                }
            })
            .collect();
        for file in fs::read_dir(&todo.trash_dir)? {
            let file = file?.path();
            verbose_println!("Checking {:#?}", file);
            if let Some(name) = file.file_name()
                && name.to_str() == Some("database.db")
            {
                verbose_println!("It's the database.");
                continue;
            }
            let file = file.canonicalize().unwrap();
            if set.contains(&file) {
                verbose_println!("It's recorded.");
                continue;
            }
            verbose_println!("It'll be cleaned.");
            fs::remove_file(file)?;
        }
        db.delete_by_time(todo.save_time)?;
    }
    // 删除主逻辑
    if todo.force {
        if todo.recursive {
            for p in todo.to_remove {
                remove_any(&p)?;
            }
        } else {
            for p in todo.to_remove {
                fs::remove_file(&p)?;
            }
        }
    } else {
        let lines: Vec<DatabaseRow> = todo
            .to_remove
            .par_iter()
            .filter_map(|p| compress::pack(p, &todo.trash_dir, todo.level).ok())
            .map(|x| x.into())
            .collect();
        db.insert_many(&lines)?;
        if !todo.save {
            for r in lines {
                remove_any(Path::new(&r.original_path))?;
            }
        }
    }
    // 恢复主逻辑
    if !todo.to_restore.is_empty() {
        let mut ids: Vec<i64> = todo.to_restore.keys().copied().collect();
        let rows = db.select_by_id(&ids)?;
        ids = rows
            .par_iter()
            .filter_map(|row| {
                Some((
                    Path::new(&row.present_path),
                    if let Some(p) = todo.to_restore.get(&row.id)? {
                        p
                    } else {
                        Path::new(&row.original_path).parent()?
                    },
                    row.id,
                ))
            })
            .filter_map(|(src, output_dir, id)| {
                compress::unpack(src, output_dir, todo.cover).ok()?;
                Some(id)
            })
            .collect();
        db.delete_by_id(&ids)?;
    }
    // 删除主逻辑
    if !todo.to_delete.is_empty() {
        db.delete_by_id(&todo.to_delete)?;
    }
    if !todo.show.is_empty() {
        db.list_by_id(&todo.show)?;
    }

    Ok(())
}

fn remove_any(path: &Path) -> std::io::Result<()> {
    let meta = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            return Ok(());
        }
        Err(e) => return Err(e),
    };
    if meta.is_dir() {
        fs::remove_dir_all(path)?;
    } else {
        fs::remove_file(path)?;
    }
    Ok(())
}

use crate::config::CoverMode;
use crate::{input, verbose_dbg, verbose_println};
use anyhow::Result;
use blake3::Hasher;
use std::fs;
use std::io::{BufReader, Read, Seek};
use std::time::SystemTime;
use std::{
    fs::File,
    io::BufWriter,
    path::{Path, PathBuf},
};
use tar::{Archive, Builder};
use zstd::{Decoder, Encoder};

/// 获取 当前毫秒时间戳 u64
#[inline]
pub fn timestamp_ms() -> u64 {
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        // 系统时钟不可能早于1970，unwrap安全
        .unwrap()
        .as_millis() as u64
}

/// 计算 人类可读的大小
#[inline]
pub fn humanized_size(size: u64) -> String {
    const KIB: u64 = 1024;
    const MIB: u64 = 1024 * KIB;
    const GIB: u64 = 1024 * MIB;
    const TIB: u64 = 1024 * GIB;
    if size < KIB {
        format!("{size}B")
    } else if size < MIB {
        format!("{:.2}KiB", size as f64 / KIB as f64)
    } else if size < GIB {
        format!("{:.2}MiB", size as f64 / MIB as f64)
    } else if size < TIB {
        format!("{:.2}GiB", size as f64 / GIB as f64)
    } else {
        format!("{:.2}TiB", size as f64 / TIB as f64)
    }
}

#[derive(Debug, Clone, Default)]
pub struct PackResult {
    pub original_path: PathBuf,
    pub present_path: PathBuf,
    pub size: String,
    pub time: u64,
}

/// 打包到指定目录下，返回PackResult
pub fn pack(src: &Path, output_dir: &Path, level: i32) -> Result<PackResult> {
    // 1. 获取时间戳
    let time = timestamp_ms();
    // 2. 打包压缩
    let mut tmp_path = output_dir.join(format!(".tmp-{time}"));
    let mut n = 0;
    // 确保不存在
    while tmp_path.exists() {
        n += 1;
        tmp_path = output_dir.join(format!(".tmp-{time}-{n}"))
    }
    let mut file = File::create(verbose_dbg!(&tmp_path))?;
    let buf_writer = BufWriter::new(&file);
    let encoder = Encoder::new(buf_writer, level)?;
    let mut tar_builder = Builder::new(encoder);
    tar_builder.append_path(src)?;
    let encoder = tar_builder.into_inner()?;
    let buf_writer = encoder.finish()?;
    drop(buf_writer);

    // 3. 求hash
    let mut hasher = Hasher::new();
    let mut buf = [0_u8; 1024 * 4];
    file.seek(std::io::SeekFrom::Start(0))?;
    loop {
        let n = file.read(&mut buf)?;
        if n == 0 {
            break;
        }
        hasher.update(&buf[..n]);
    }
    let hash = verbose_dbg!(hasher.finalize().to_string());

    // 4. 改名
    // 如果哈希一样，说明是同一份文件，允许覆盖，节省储存空间
    let path = output_dir.join(format!("{hash}.bak"));
    fs::rename(tmp_path, &path)?;

    // 5. 构建返回值
    let size = humanized_size(file.metadata()?.len());
    verbose_println!("Pack {:#?} to {:#?}", src, output_dir);
    Ok(PackResult {
        original_path: src.into(),
        present_path: path,
        size,
        time,
    })
}

/// 解包到指定目录
pub fn unpack(src: &Path, output_dir: &Path, cover: CoverMode) -> Result<()> {
    let file = File::open(src)?;
    let buf_reader = BufReader::new(file);
    let decoder = Decoder::new(buf_reader)?;
    let mut archive = Archive::new(decoder);
    fs::create_dir_all(output_dir)?;
    match cover {
        CoverMode::Always => {
            archive.unpack(output_dir)?;
        }
        _ => {
            for entry_result in archive.entries()? {
                let mut entry = entry_result?;
                let path = entry.path()?.to_path_buf();
                let dest = output_dir.join(&path);
                if dest.exists() {
                    match cover {
                        CoverMode::Always => {
                            unreachable!();
                        }
                        CoverMode::Never => {}
                        CoverMode::Ask => {
                            match input!("{:#?} is exists, do you want to cover it?[Y/n] ", dest)
                                .as_str()
                            {
                                "Y" | "y" => {
                                    entry.unpack_in(output_dir)?;
                                }
                                _ => {}
                            }
                        }
                    }
                } else {
                    entry.unpack_in(output_dir)?;
                }
            }
        }
    }
    verbose_println!("Unpack {:#?} to {:#?}", src, output_dir);
    Ok(())
}

use crate::cli::Cli;
use crate::{VERBOSE, verbose_dbg};
use anyhow::Result;
use clap::{Parser, ValueEnum};
use dirs_next::home_dir;
use figment::{
